/* Generated by gen_packs.py from the original data files: pack "ncrawler". */
MC.registerPack({"id":"ncrawler","cards":[{"id":"48001a","name":"나이트크롤러","en":"* Nightcrawler","type":"hero","enc":false,"unique":true,"hp":9,"atk":1,"thw":2,"def":3,"hs":5,"tr":["X-MEN"],"traits":["엑스맨"],"text":"<i>고속 순간이동</i> — <b>행동</b>: 아무 유형의 자원 1개를 소모 → 당신의 버린 더미에서 뱀프! 1장을 당신의 손으로 되돌림. (페이즈마다 1회 제한.)"},{"id":"48001b","name":"커트 와그너","en":"* Kurt Wagner","type":"alter","enc":false,"unique":true,"hp":9,"rec":3,"hs":6,"tr":["MUTANT"],"traits":["뮤턴트"],"text":"<b>행동</b>: 당신의 덱에서 뱀프! 1장을 찾아 당신의 손에 더합니다. (라운드마다 1회 제한.)"},{"id":"48002","name":"데이트리퍼","en":"* Daytripper","type":"ally","enc":false,"sub":"아만다 세프턴","unique":true,"hp":2,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":2,"res":"G","cls":"Hero","tr":["MYSTIC"],"traits":["신비주의자"],"text":"<b>반응</b>: 데이트리퍼가 플레이 영역에 들어온 후, 당신의 덱과 버린 더미에서 뱀프! 1장을 찾아 적 하나에게 장착합니다. 뱀프!가 장착된 각 적에게 피해 1점을 입힙니다."},{"id":"48003","name":"커트의 예배당","en":"* Kurt's Chapel","type":"support","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["LOCATION"],"traits":["장소"],"text":"커트 와그너는 회복 +1을 받습니다.\n<b>일상 반응</b>: 당신이 기본 회복을 한 후, 커트의 예배당을 소진하고 플레이어 하나를 선택 → 그 플레이어가 카드 1장을 뽑음."},{"id":"48004","name":"커트의 커틀러스","en":"* Kurt's Cutlasses","type":"upgrade","enc":false,"unique":true,"cost":2,"res":"R","cls":"Hero","tr":["WEAPON"],"restricted":2,"traits":["무기"],"text":"한정 카드 2장으로 취급합니다.\n나이트크롤러는 공격 +1, 방어 +1을 받고 반격 1을 얻습니다."},{"id":"48005","name":"감아쥐는 꼬리","en":"* Prehensile Tail","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"R","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"당신은 한정 키워드를 가진 업그레이드를 1장 더 조종할 수 있습니다.\n<b>자원</b>: 감아쥐는 꼬리를 소진 → 이벤트를 위한 [wild] 자원을 생성."},{"id":"48006","name":"뱀프!","en":"Bamf!","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"R","cls":"Hero","tr":[],"maxPer":1,"traits":[],"text":"적 하나에게 장착합니다. 적마다 최대 1장.\n<b>히어로 난입</b><i>(방어)</i>: 장착된 적이 공격할 때, 이 카드를 버림 → 나이트크롤러를 소진하지 않고 방어자로 선언."},{"id":"48007","name":"순간이동 펀치","en":"'Port and Punch","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 3점을 입힙니다. 뱀프!가 장착된 각 적에게 피해 3점을 입힙니다."},{"id":"48008","name":"순간이동 낙하","en":"Teleport Drop","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게서 뱀프! 1장을 버림 → 그 적에게 피해 8점을 입히고 그 적을 기절시킴."},{"id":"48009","name":"선행 정찰","en":"Scout Ahead","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["SUPERPOWER","THWART"],"traits":["슈퍼파워","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 3만큼 제거합니다. 당신의 손에서 뱀프! 1장을 버려 다른 음모 하나에서 위협을 3만큼 제거해도 됩니다."},{"id":"48010","name":"순간이동 탈출","en":"'Port Away","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>행동</b>: 당신의 손에서 뱀프! 1장을 버림 → 형태를 바꾸고 당신의 아이덴티티를 준비."},{"id":"48011","name":"돌격!","en":"Tally Ho!","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero","tr":["DEFENSE","SUPERPOWER"],"traits":["방어","슈퍼파워"],"text":"<b>히어로 반응</b><i>(방어)</i>: 뱀프!로 인해 나이트크롤러가 공격의 방어자가 된 후, 그 뱀프!를 당신의 손으로 되돌립니다. 공격하는 적에게 피해 3점을 입힙니다."},{"id":"48012","name":"로그","en":"* Rogue","type":"ally","enc":false,"sub":"애나 마리","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"R","cls":"Protection","tr":["X-MEN"],"traits":["엑스맨"],"text":"<b>행동</b>: 다른 아군 캐릭터 하나에게 피해 1점을 입힘 → 라운드가 끝날 때까지, 로그는 그 캐릭터의 모든 [[특성]]을 얻고 그 캐릭터의 인쇄된 저지와 공격을 자신의 해당 능력치에 더함. (라운드마다 1회 제한.)"},{"id":"48013","name":"노스스타","en":"* Northstar","type":"ally","enc":false,"sub":"장폴 보비에","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Protection","tr":["X-MEN"],"traits":["엑스맨"],"text":"<b>난입</b>: 공격 중에 강화 카드가 앞면으로 뒤집힐 때, 노스스타에게 피해 1점을 입힘 → 그 카드의 모든 강화 아이콘([boost])을 무효화."},{"id":"48014","name":"운명의 반전","en":"Change of Fortune","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Protection","tr":[],"maxPer":1,"traits":[],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n<b>반응</b>: 당신이 빌런 페이즈 중 적을 격파한 후, 이 카드를 소진 → 카드 2장을 뽑음."},{"id":"48015","name":"통제 완료","en":"Under Control","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Protection","tr":["TACTIC"],"maxPer":1,"traits":["전술"],"text":"하수인 하나에게 장착합니다. 하수인마다 최대 1장.\n<b>반응</b>: 히어로가 장착된 하수인의 공격을 방어하고 피해를 입지 않은 후, 장착된 하수인에게 피해 4점을 입힙니다."},{"id":"48016","name":"\"덤벼 봐, 애송이!\"","en":"\"Come Get Me, Bub!\"","type":"event","enc":false,"unique":false,"cost":0,"res":"B","cls":"Protection","tr":["TACTIC"],"traits":["전술"],"text":"<b>히어로 행동</b>: 하수인이 버려질 때까지 조우 덱에서 카드를 버립니다. 그 하수인을 당신과 교전 중인 채로 플레이 영역에 내려놓음 → 당신의 아이덴티티가 입은 피해 3점을 치료하고 당신의 아이덴티티에게 강인함 상태 카드를 줌."},{"id":"48017","name":"강력한 펀치","en":"Powerful Punch","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Protection","tr":["ATTACK","DEFENSE"],"traits":["공격","방어"],"text":"<b>히어로 난입</b><i>(공격/방어)</i>: 적이 공격을 개시할 때, 그 적에게 피해 4점을 입힙니다.","link":"32014"},{"id":"48018","name":"되받아치기","en":"Riposte","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Protection","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신의 히어로가 공격을 방어할 때, 그 히어로는 그 공격에 대해 방어 +2를 받습니다. 그 공격으로 당신이 피해를 입지 않았다면, 공격하는 적에게 피해 3점을 입힙니다."},{"id":"48019","name":"수호의 힘","en":"The Power of Protection","type":"resource","enc":false,"unique":false,"res":"G","cls":"Protection","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n수호<i>(녹색)</i> 카드에 이 카드를 비용으로 지불하는 한, 이 카드가 생성하는 자원은 2배가 됩니다.","link":"01079"},{"id":"48020","name":"어스토니싱 엑스맨","en":"* Astonishing X-Men","type":"pside","enc":false,"unique":true,"cost":1,"start":5,"res":"R","cls":"Protection","tr":[],"victory":0,"traits":[],"text":"승점 0.\n<b>반응</b>: [[엑스맨]] 캐릭터가 적의 공격을 방어하고 피해를 입지 않은 후, 이 음모에서 위협을 1만큼 제거합니다.\n<b>격파될 때</b>: 플레이 영역에 있는 각 적을 기절시키고 혼란에 빠뜨립니다."},{"id":"48021","name":"갬빗","en":"* Gambit","type":"ally","enc":false,"sub":"레미 르보","unique":true,"hp":3,"atk":0,"atkStar":true,"thw":0,"thwStar":true,"cost":3,"res":"Y","cls":"Basic","tr":["THIEF","X-MEN"],"traits":["도둑","엑스맨"],"text":"X는 갬빗 밑에 있는 카드의 강화 아이콘([boost]) 수입니다.\n<b>반응</b>: 갬빗이 플레이 영역에 들어온 후, 조우 덱 맨 위 카드 3장을 보고 그중 1장을 강화 영역만 보이도록 갬빗 밑에 끼워 넣습니다."},{"id":"48022","name":"모이라 맥태거트","en":"* Moira MacTaggert","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Basic","tr":["PERSONA"],"traits":["페르소나"],"text":"당신의 아이덴티티가 [[뮤턴트]] 특성을 가지고 있을 때만 플레이합니다.\n<b>반응</b>: [[뮤턴트]] 일상이 히어로 형태로 변신한 후, 모이라 맥태거트를 소진 → 그 히어로를 조종하는 플레이어가 카드 1장을 뽑음.","link":"38018"},{"id":"48023","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"48024","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"48025","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"48026","name":"신앙의 위기","en":"Crisis of Faith","type":"obligation","enc":true,"set":"Nightcrawler","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>커트 와그너 플레이어에게 이 카드를 줍니다.</i></b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 커트 와그너를 소진 → 신앙의 위기를 게임에서 제거.\n• 당신의 손에서 [[공격]] 및 [[방어]] 이벤트를 모두 버립니다. 이 의무 카드를 버립니다."},{"id":"48027","name":"아자젤","en":"* Azazel","type":"minion","enc":true,"set":"Nightcrawler Nemesis","unique":true,"hp":3,"atk":3,"sch":2,"tr":["ELITE","NEYAPHEM"],"quickstrike":1,"nemesis":true,"traits":["간부","네야펨"],"text":"속공.\n아자젤에게는 업그레이드를 장착할 수 없습니다.\n<hr />\n[star] <b>강화</b>: 아자젤을 뒷면 조우 카드로 커트 와그너 플레이어에게 나누어 줍니다.","star":true,"boostStar":true},{"id":"48028","name":"유황 차원","en":"Brimstone Dimension","type":"side","enc":true,"set":"Nightcrawler Nemesis","unique":false,"boost":3,"start":5,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 이 음모를 격파한 플레이어는 아자젤을 찾아 뒷면 조우 카드로 자신에게 나누어 줍니다."},{"id":"48029","name":"아자젤 검","en":"Azazel's Sword","type":"attachment","enc":true,"set":"Nightcrawler Nemesis","unique":false,"boost":2,"plus":{"atk":1},"tr":["WEAPON"],"traits":["무기"],"text":"아자젤에게 장착합니다. 그럴 수 없다면, 빌런에게 장착합니다.\n[star] 장착된 적의 공격은 관통을 얻습니다.\n<b>히어로 반응</b>: 장착된 적이 당신을 공격한 후, 당신의 손에서 무작위로 카드 1장을 버림 → 이 카드를 버림.","star":true},{"id":"48030","name":"유황 일격","en":"Brimstone Strike","type":"treachery","enc":true,"set":"Nightcrawler Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 아자젤을 찾아 공개합니다. 그가 암약합니다.\n<b>공개될 때(히어로)</b>: 아자젤을 찾아 공개합니다."},{"id":"48031","name":"힘 합치기","en":"Combine Forces","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Aggression","tr":[],"alliance":1,"traits":[],"text":"동맹.\n<b>히어로 행동</b>: [[엑스포스]] 캐릭터 하나와 [[엑스맨]] 캐릭터 하나를 소진 → [[간부]]가 아닌 하수인 하나를 격파."},{"id":"48032","name":"포함 외교","en":"Gunboat Diplomacy","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":["ATTACK","THWART"],"alliance":1,"traits":["공격","저지"],"text":"동맹.\n<b>히어로 행동</b><i>(공격/저지)</i>: [[엑스포스]] 캐릭터 하나와 [[엑스맨]] 캐릭터 하나를 소진 → 플레이 영역에 있는 음모들에서 위협을 총 X만큼 나누어 제거하고 플레이 영역에 있는 적들에게 피해 X점을 나누어 입힘. X는 소진된 두 캐릭터의 저지를 합한 값입니다."},{"id":"48033","name":"크레이지 갱","en":"The Crazy Gang","type":"side","enc":true,"set":"Crazy Gang","unique":false,"boost":2,"start":2,"accel":1,"tr":[],"traits":[],"text":"<b>강제 반응</b>: [[간부]]가 아닌 하수인이 플레이어를 상대로 암약한 후, 그 하수인을 뒷면 조우 카드로 그 플레이어에게 나누어 줍니다. 그러고 나서, 게임에 플레이어가 2명 이상이라면, 그 뒷면 조우 카드를 다음 플레이어에게 넘깁니다."},{"id":"48034","name":"하트 여왕","en":"* Queen of Hearts","type":"minion","enc":true,"set":"Crazy Gang","unique":true,"hp":4,"atk":1,"sch":0,"boost":3,"tr":["CRIMINAL","QUEEN"],"traits":["범죄자","여왕"],"text":"<b>공개될 때</b>: 조우 덱과 조우 버린 더미에서 크레이지 갱 부가 음모를 찾아 공개합니다. 이미 플레이 영역에 있다면, 자신에게 조우 카드 1장을 뒷면으로 나누어 줍니다. <i>(섞습니다.)</i>"},{"id":"48035","name":"제스터","en":"* Jester","type":"minion","enc":true,"set":"Crazy Gang","unique":true,"hp":5,"atk":1,"sch":0,"boost":1,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 당신은 혼란에 빠집니다. 이미 혼란 상태였다면, 당신이 조종하는 지원 카드 하나를 버립니다."},{"id":"48036","name":"사형 집행인","en":"* Executioner","type":"minion","enc":true,"set":"Crazy Gang","unique":true,"hp":4,"atk":2,"sch":0,"boost":2,"tr":["CRIMINAL"],"traits":["범죄자"],"text":"<b>공개될 때</b>: 사형 집행인이 남은 생명력이 가장 적은 아군 캐릭터를 공격합니다. 이 공격으로 동료가 격파되면, 그 동료를 게임에서 제거합니다."},{"id":"48037","name":"트위들도프","en":"* Tweedledope","type":"minion","enc":true,"set":"Crazy Gang","unique":true,"hp":6,"atk":2,"sch":0,"boost":1,"tr":["BRUTE","CRIMINAL"],"traits":["야만","범죄자"],"text":"<b>공개될 때</b>: 당신은 기절합니다. 이미 기절 상태였다면, 당신이 조종하는 업그레이드 하나를 버립니다."},{"id":"48038","name":"\"저놈의 목을 쳐라!\"","en":"\"Off with His Head!\"","type":"treachery","enc":true,"set":"Crazy Gang","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 하수인이 자신과 교전 중인 플레이어를 상대로 활성화합니다. 이렇게 활성화한 하수인이 없다면, 하수인이 버려질 때까지 조우 덱 맨 위에서부터 카드를 버리고 그 하수인을 공개합니다."}]});
